// Üretilen dosya: tool/ozgun/uret.py. Tarih · Türk-İslam devletleri ve Selçuklular (kolay).
const ozHistory2Kolay = <(String, String, List<String>, String)>[
  ('Emevilerin Arap olmayan Müslümanlara (mevali) ikinci sınıf muamele etmesi, Türklerin İslamiyet\'e yaklaşımını nasıl etkilemiştir?', 'İslamiyet\'in Türkler arasında yayılmasını yavaşlatmıştır', ['Türklerin kitleler hâlinde ve kısa sürede Müslüman olmasını hızlandırmıştır', 'Türklerin Emevi ordusunda komutan olmasını sağlamıştır', 'Türklerin Bizans\'la ittifakını sona erdirmiştir'], 'Emevilerin Arap milliyetçiliğine dayalı politikası ve mevaliden ağır vergi alması, Türklerin bu dönemde İslam\'a mesafeli kalmasına yol açtı.'),
  ('751 yılındaki Talas Savaşı\'nda Abbasi ordusu hangi devletin ordusuyla karşı karşıya gelmiştir?', 'Çin', ['Bizans İmparatorluğu', 'Sasani İmparatorluğu', 'Hazar Kağanlığı'], 'Talas Savaşı\'nda Ziyad bin Salih komutasındaki Abbasi ordusu ile Kao Hsien-chih komutasındaki Tang Çini ordusu çarpıştı.'),
  ('Talas Savaşı sırasında Çin saflarından ayrılıp Abbasilerin yanına geçerek savaşın sonucunu belirleyen Türk boyu hangisidir?', 'Karluklar', ['Oğuzlar', 'Kıpçaklar', 'Peçenekler'], 'Karlukların taraf değiştirmesi Çin ordusunun ağır bir yenilgi almasında belirleyici oldu.'),
  ('Talas Savaşı\'ndan sonra esir alınan Çinli ustalar aracılığıyla Semerkant\'ta üretimi başlayan ve İslam dünyasında bilginin yayılmasını hızlandıran ürün hangisidir?', 'Kâğıt', ['Barut', 'Pusula', 'İpek kumaş'], 'Çinli esirler Semerkant\'ta kâğıt imalathaneleri kurdu; kâğıt buradan İslam dünyasına ve daha sonra Avrupa\'ya yayıldı.'),
  ('Talas Savaşı\'nın Orta Asya tarihi açısından en önemli sonucu aşağıdakilerden hangisidir?', 'Çin\'in Orta Asya\'daki ilerleyişinin durması', ['Abbasi Halifeliğinin yıkılması', 'Göktürk Devleti\'nin Çin desteğiyle yeniden kurulması', 'Moğolların batıya göç etmesi'], 'Talas\'tan sonra Çin uzun süre Orta Asya\'ya müdahale edemedi; bu durum Türk-Arap yakınlaşmasını ve İslamiyet\'in yayılmasını kolaylaştırdı.'),
  ('Abbasi halifesi Mutasım\'ın, Bağdat halkı ile Türk askerleri arasında çıkan anlaşmazlıklar üzerine Türk askerleri için kurdurduğu şehir hangisidir?', 'Samarra', ['Kufe', 'Basra', 'Rakka'], 'Mutasım 836 yılında Dicle kıyısında Samarra\'yı kurdurdu ve Türk askerlerini buraya yerleştirdi.'),
  ('Abbasiler döneminde Türklerin ordu ve yönetimde güç kazanmasının temel nedeni aşağıdakilerden hangisidir?', 'Türklerin askerî yetenekleri ve halifeye sadakatleri', ['Türklerin Arapça bilmemesi nedeniyle tarafsız görülmesi', 'Türklerin halifeye büyük vergi ödemesi', 'Türklerin şehirli ve tüccar bir toplum olması'], 'Abbasi halifeleri, Arap ve İran kökenli unsurlara karşı denge kurmak için savaşçılığıyla bilinen Türkleri orduya aldı ve onlara güvendi.'),
  ('Türklerin büyük topluluklar hâlinde İslamiyet\'e girmesi en çok hangi dönemde gerçekleşmiştir?', 'Abbasiler döneminde', ['Hz. Ebubekir döneminde', 'Hz. Osman döneminde', 'Emevilerin kuruluş yıllarında'], 'Abbasilerin Arap olmayan Müslümanlara eşit davranması ve Talas sonrası yakınlaşma, Türklerin kitleler hâlinde Müslüman olmasını sağladı.'),
  ('Mısır\'da Abbasi valisi olarak göreve başlayıp yönetimi kendi ailesine bağlayan ve Mısır\'da kurulan ilk Türk devletinin kurucusu kimdir?', 'Ahmed bin Tolun', ['Muhammed bin Tuğç', 'Kafur', 'Ahmed bin Tuğç'], 'Ahmed bin Tolun 868\'de Mısır\'a vali olarak gönderildi ve kısa sürede bağımsız hareket eden Tolunoğulları Devleti\'ni kurdu.'),
  ('Mısır\'da kurulan ikinci Türk devleti olan İhşidilerin kurucusu kimdir?', 'Muhammed bin Tuğç', ['Ahmed bin Tolun', 'Humareveyh bin Ahmed', 'Alp Tegin'], 'Muhammed bin Tuğç 935\'te Mısır valisi oldu; halifeden \'İhşid\' unvanını alınca devlet bu adla anıldı.'),
  ('İhşidilerin hâkimiyet alanında bulunan Mekke ve Medine\'nin, İslam dünyasında devlete kazandırdığı en önemli üstünlük nedir?', 'Siyasi ve dinî itibarın artması', ['Baharat yolunun tamamen denetlenmesi', 'Bizans\'a karşı doğal bir sınır oluşması', 'Abbasilerden bağımsızlığın resmen tanınması'], 'Kutsal şehirlerin denetimi, İhşidilere İslam dünyasında büyük saygınlık kazandırdı.'),
  ('Karahanlı hükümdarlarından hangisi Müslüman olarak \'Abdülkerim\' adını almış ve İslamiyet\'in devlet içinde yayılmasına öncülük etmiştir?', 'Satuk Buğra Han', ['Bilge Kül Kadir Han', 'Tamgaç Buğra Han', 'Arslan İlig Nasr'], 'Satuk Buğra Han Müslüman olduktan sonra Abdülkerim adını aldı; onun döneminde Karahanlılar İslam\'a geçti.'),
  ('Karahanlıların Samanoğulları Devleti\'ne son vermesi, Türk tarihi açısından hangi sonucu doğurmuştur?', 'Maveraünnehir\'de Türk egemenliği kesinleşmiştir', ['Karahanlılar Bağdat\'ı ele geçirip halifeyi korumaya almıştır', 'Gazneliler Karahanlılara bağlanmıştır', 'Oğuzlar Anadolu\'ya yerleşmiştir'], '999 yılında Buhara\'nın alınmasıyla Samanoğulları yıkıldı; Maveraünnehir İran etkisinden çıkıp Türk yönetimine girdi.'),
  ('Karahanlılar döneminde Türkçenin resmî dil olarak kullanılması ve Türkçe eserler yazılması aşağıdakilerden hangisini gösterir?', 'Türk kültürünün İslam\'la birlikte korunduğunu', ['Arapçanın bölgede hiç bilinmediğini', 'Karahanlıların Abbasilerle savaş hâlinde olduğunu', 'Farsçanın yasaklandığını'], 'Karahanlılar İslam\'ı kabul etmelerine rağmen Türkçeyi ve Türk geleneklerini sürdürdüler; bu durum Türk-İslam kültürünün oluşumunu sağladı.'),
  ('Yusuf Has Hacip tarafından yazılan Kutadgu Bilig\'in temel konusu nedir?', 'Devlet yönetimi ve mutluluğa ulaşmanın yolları', ['Türk boylarının soy kütükleri ve göç yolları', 'Arapça ve Türkçenin dil bilgisi kurallarının karşılaştırılması', 'Türk destanlarının derlenmesi'], 'Kutadgu Bilig \'mutluluk veren bilgi\' anlamına gelir; ideal devlet yönetimi ve insanın iki dünyada mutluluğu konu edilir.'),
  ('Kaşgarlı Mahmut\'un Divanü Lügati\'t-Türk\'ü yazmasındaki temel amaç nedir?', 'Araplara Türkçeyi öğretmek ve Türkçenin zenginliğini göstermek', ['Türklere Arapçayı ve Kur\'an\'ın dilini dil bilgisi kurallarıyla öğretmek', 'Farsça şiirleri Türkçeye çevirmek', 'İslam hukukunu Türkçe açıklamak'], 'Kaşgarlı Mahmut eserini Abbasi halifesine sunmuş, Türkçenin Arapça kadar zengin bir dil olduğunu kanıtlamayı amaçlamıştır.'),
  ('Kaşgarlı Mahmut, Divanü Lügati\'t-Türk\'ü hangi şehirde yazıp Abbasi halifesine sunmuştur?', 'Bağdat', ['Kaşgar', 'Semerkant', 'Buhara'], 'Kaşgarlı Mahmut eserini 1072-1077 yılları arasında Bağdat\'ta yazarak Halife Muktedi Biemrillah\'a sundu.'),
  ('Edip Ahmet Yükneki\'nin Atabetü\'l-Hakayık adlı eseri hangi türde değerlendirilir?', 'Dinî-ahlaki öğüt kitabı', ['Hükümdarlık üzerine yazılmış tarih kroniği', 'Sözlük', 'Tıp kitabı'], 'Atabetü\'l-Hakayık \'hakikatlerin eşiği\' anlamına gelir; cömertlik, bilgi, dil korunması gibi ahlaki konularda öğütler içerir.'),
  ('Ahmet Yesevi\'nin dörtlüklerden oluşan ve tasavvufi düşünceyi sade bir Türkçe ile halka anlatan eseri hangisidir?', 'Divan-ı Hikmet', ['Kutadgu Bilig', 'Mesnevi-i Manevi', 'Garipname'], 'Ahmet Yesevi hikmet adı verilen şiirlerini Divan-ı Hikmet\'te topladı; sade dil, İslam\'ın göçebe Türkler arasında yayılmasını kolaylaştırdı.'),
  ('Gazneli Devleti\'nin kuruluşu, Samanoğulları ordusunda görev yapan hangi Türk komutanın Gazne\'ye yerleşmesiyle başlamıştır?', 'Alp Tegin', ['Sebük Tegin', 'Tuğrul Tegin', 'Arslan Yabgu'], 'Samanoğullarının Horasan komutanı Alp Tegin 962\'de Gazne\'yi alarak kendine bağlı bir yönetim kurdu.'),
  ('Gazneli Mahmut\'un Hindistan\'a düzenlediği seferlerin sayısı kaynaklarda genellikle kaç olarak verilir?', 'On yedi', ['Yedi', 'On iki', 'Yirmi beş'], 'Gazneli Mahmut 1001-1027 yılları arasında Hindistan\'a on yedi sefer düzenledi.'),
  ('Gazneli Mahmut\'un Hindistan seferleri sonucunda bu bölgede ortaya çıkan en kalıcı gelişme aşağıdakilerden hangisidir?', 'İslamiyet\'in Hint Yarımadası\'nda yayılmaya başlaması', ['Hindistan\'ın tamamının kısa sürede Gazne\'ye katılması', 'Budizm\'in Hindistan\'da resmî din olması', 'Hindistan\'ın Çin\'e bağlanması'], 'Seferlerle Pencap bölgesi Gaznelilere bağlandı; İslamiyet ve Türk-İslam kültürü Hindistan\'a girmeye başladı.'),
  ('Kaynaklarda \'sultan\' unvanını kullanan ilk Türk-İslam hükümdarı olarak anılan kişi kimdir?', 'Gazneli Mahmut', ['Tuğrul Bey', 'Alparslan', 'Satuk Buğra Han'], 'Gazneli Mahmut halifeden \'Yeminü\'d-Devle\' unvanını almış ve \'sultan\' unvanını kullanan ilk Türk hükümdarı olarak anılmıştır; bu unvanı halifeden resmen alan ise Tuğrul Bey\'dir.'),
  ('İran\'ın destansı tarihini anlatan Şehname\'yi Gazneli Mahmut\'a sunan şair kimdir?', 'Firdevsi', ['Ömer Hayyam', 'Sadi Şirazi', 'Hafız'], 'Firdevsi Şehname\'yi otuz yılda tamamlayıp Gazneli Mahmut\'a sundu; eser Fars edebiyatının en önemli destanıdır.'),
  ('Gazneliler, Abbasi halifesine bağlılıklarını aşağıdakilerden hangisiyle göstermişlerdir?', 'Hutbede halifenin adını okutarak', ['Halifenin ordusuna her yıl asker göndererek', 'Başkentlerini Bağdat\'a taşıyarak', 'Halifeyi Gazne\'ye davet ederek'], 'Hutbe ve sikkede halifenin adının yer alması, Türk-İslam devletlerinde halifeye bağlılığın simgesiydi.'),
  ('Selçukluların adını aldığı Selçuk Bey\'in, Oğuz Yabgu Devleti\'nde \'subaşı\' olarak görev yaptığı bilinmektedir. Selçuk Bey ve ailesi hangi Oğuz boyundandır?', 'Kınık', ['Kayı', 'Bayındır', 'Avşar'], 'Selçuklu hanedanı Oğuzların Kınık boyundandır; Selçuk Bey, Oğuz Yabgusunun ordu komutanı (subaşı) idi.'),
  ('Selçuk Bey\'in Oğuz Yabgusundan ayrıldıktan sonra yerleştiği ve Müslüman olduğu kabul edilen Seyhun kıyısındaki şehir hangisidir?', 'Cend', ['Merv', 'Nişabur', 'Otrar'], 'Selçuk Bey ve maiyeti Cend\'e yerleşerek Müslüman oldu ve buradaki Müslüman halkı yabguya vergi vermekten kurtardı.'),
  ('Selçuk Bey\'in Cend\'de Oğuz Yabgusunun vergi memurlarını geri göndermesi, Selçuklu tarihi açısından ne ifade eder?', 'Bağımsız bir siyasi hareketin başlangıcını', ['Oğuz Yabgusuna tam bağlılığın yeniden onaylanmasını', 'Karahanlılarla birleşmeyi', 'Gaznelilere vergi ödemeye başlamayı'], 'Bu olay Selçuk Bey\'in yabgudan fiilen ayrılarak bağımsız hareket etmeye başladığını gösterir.'),
  ('Tuğrul ve Çağrı beylerin 1035\'te Gaznelileri yendiği ve Nesa, Ferava, Dihistan bölgelerini aldığı savaş hangisidir?', 'Nesa Savaşı', ['Dandanakan Savaşı', 'Katvan Savaşı', 'Pasinler Savaşı'], 'Nesa zaferiyle Gazneliler Selçuklulara bu bölgeleri bırakmak zorunda kaldı; Selçuklular ilk kez toprak sahibi oldu.'),
  ('Dandanakan Savaşı\'nın Gazneliler açısından sonucu aşağıdakilerden hangisidir?', 'Gaznelilerin Hindistan\'a çekilerek bölgesel bir devlete dönüşmesi', ['Gaznelilerin Selçuklulara bağlanarak her yıl ağır vergi ödemeye başlaması', 'Gaznelilerin Anadolu\'ya göç etmesi', 'Gaznelilerin Abbasileri ortadan kaldırması'], 'Yenilgiden sonra Gazneliler Horasan\'ı kaybedip Afganistan ve Hindistan\'la sınırlı kaldı.'),
  ('Tuğrul Bey\'in 1055\'te Bağdat\'a girmesinin temel nedeni aşağıdakilerden hangisidir?', 'Halifeyi Şii Büveyhoğulları baskısından kurtarmak', ['Bizans ordusunun Bağdat\'ı kuşatma girişimini önceden önlemek', 'Gaznelilerin Bağdat\'a yerleşmesini engellemek', 'Fatımileri Mısır\'dan çıkarmak'], 'Abbasi halifesi Kaim Biemrillah, Büveyhilerin ve Besasiri\'nin baskısından kurtulmak için Tuğrul Bey\'i çağırdı.'),
  ('Tuğrul Bey\'e Abbasi halifesi tarafından verilen ve Selçukluların İslam dünyasının siyasi liderliğini üstlendiğini simgeleyen unvan hangisidir?', 'Doğunun ve Batının Sultanı', ['Emirü\'l-Müminin', 'Halife-i Rûy-i Zemin', 'Hâkimü\'l-Haremeyn eş-Şerifeyn'], 'Halife, Tuğrul Bey\'i \'Sultanü\'l-Meşrık ve\'l-Mağrib\' ilan etti; bu unvan siyasi yetkinin Selçuklu sultanına geçtiğini gösteriyordu.'),
  ('Tuğrul Bey 1063\'te öldüğünde Büyük Selçuklu tahtına çıkan Alparslan, Tuğrul Bey\'in neyi olur?', 'Yeğeni', ['Oğlu', 'Kardeşi', 'Torunu'], 'Alparslan, Tuğrul Bey\'in kardeşi Çağrı Bey\'in oğluydu; çocuğu olmayan Tuğrul\'un yerine geçti.'),
  ('Alparslan\'ın Malazgirt\'te Bizans ordusunu yenmesinde etkili olan ve geri çekiliyormuş gibi yapıp düşmanı pusuya düşürmeye dayanan Türk savaş taktiği hangisidir?', 'Hilal (Turan) taktiği', ['Falanks düzeni', 'Kuşatma kuleleri', 'Ateşli silah üstünlüğü'], 'Sahte ricat ve kuşatmaya dayanan hilal taktiği, Türk ordularının bozkır kökenli klasik savaş yöntemidir.'),
  ('Malazgirt Savaşı\'ndan sonra Romen Diyojen\'in tahttan indirilmesi ve antlaşmanın Bizans tarafından tanınmaması hangi sonucu doğurmuştur?', 'Türk beylerinin Anadolu içlerine hızla ilerlemesi', ['Selçukluların Anadolu\'dan çekilip Horasan\'a geri dönmesi', 'Bizans\'ın Kudüs\'ü ele geçirmesi', 'Haçlı Seferleri\'nin sona ermesi'], 'Antlaşmanın geçersiz sayılması üzerine Alparslan komutanlarına Anadolu\'yu fethetme görevi verdi; Türkmen akınları hız kazandı.'),
  ('\'Malazgirt Savaşı, Anadolu\'nun kapılarını Türklere açmıştır.\' yargısı aşağıdakilerden hangisiyle en iyi açıklanır?', 'Bizans\'ın doğu savunmasının çökmesiyle Türkmen yerleşiminin kolaylaşması', ['Savaştan hemen sonra İstanbul\'un kuşatılıp Türklerce fethedilmesi ve Bizans\'ın yıkılması', 'Anadolu\'daki tüm Hristiyanların göç etmesi', 'Abbasi halifesinin Anadolu\'ya taşınması'], 'Bizans ordusunun yenilgisi doğu sınırını savunmasız bıraktı; Türkmen boyları kitleler hâlinde Anadolu\'ya yerleşmeye başladı.'),
  ('Büyük Selçuklu Devleti\'nin en geniş sınırlara ulaştığı ve \'altın çağı\' olarak anılan dönem hangi sultanın hükümdarlığıdır?', 'Melikşah', ['Tuğrul Bey', 'Berkyaruk', 'Sencer'], 'Melikşah döneminde (1072-1092) devletin sınırları Kaşgar\'dan Akdeniz\'e, Kafkasya\'dan Yemen\'e kadar genişledi.'),
  ('Melikşah döneminde Ömer Hayyam başkanlığındaki bir heyet tarafından hazırlanan ve güneş yılına dayanan takvim hangisidir?', 'Celali Takvimi', ['Hicri Takvim', 'Rumi Takvim', 'On İki Hayvanlı Takvim'], 'Melikşah\'ın unvanı Celaleddin olduğundan takvime Celali adı verildi; takvim büyük bir doğrulukla güneş yılını hesapladı.'),
  ('Alparslan ve Melikşah dönemlerinde uzun yıllar vezirlik yapan ve Siyasetname\'nin yazarı olan devlet adamı kimdir?', 'Nizamülmülk', ['Amidülmülk Kündüri', 'Tacülmülk', 'Ebu Said'], 'Nizamülmülk yaklaşık otuz yıl vezirlik yaptı; devlet teşkilatı ve eğitim alanında kalıcı düzenlemelere imza attı.'),
  ('Nizamülmülk\'ün Siyasetname\'yi yazma amacı aşağıdakilerden hangisidir?', 'Hükümdara devlet yönetimi konusunda yol göstermek', ['Selçuklu hanedanının soyunu ve Oğuz kökenini ayrıntılı anlatmak', 'Fıkıh kurallarını derlemek', 'Fars şiirini Türkçeye aktarmak'], 'Siyasetname, Melikşah\'ın isteği üzerine yazılmış; adalet, vergi, ordu ve devlet görevlileri hakkında öğütler içeren bir eserdir.'),
  ('Nizamülmülk 1092 yılında hangi grup mensubu bir fedai tarafından öldürülmüştür?', 'Batıniler', ['Haçlılar', 'Karmatiler', 'Hariciler'], 'Nizamülmülk, Hasan Sabbah\'a bağlı bir Batıni fedaisinin saldırısıyla Nihavend yakınlarında öldürüldü.'),
  ('Hasan Sabbah\'ın Batıni hareketinin merkezi olarak kullandığı, İran\'ın Elburz Dağları\'ndaki kale hangisidir?', 'Alamut', ['Kalincar', 'Berzem', 'Alanya'], 'Hasan Sabbah 1090\'da Alamut Kalesi\'ni ele geçirdi; burası Batınilerin siyasi ve dinî merkezi oldu.'),
  ('Melikşah\'ın ölümünden sonra Büyük Selçuklu Devleti\'nde taht kavgalarının artmasının temel nedeni hangisidir?', 'Ülkenin hanedan üyelerinin ortak malı sayılması', ['Sultanların halife tarafından atanması', 'Veraset sisteminde ekber ve erşed usulünün uygulanması', 'Ordunun tamamen paralı askerlerden oluşması'], 'Eski Türk anlayışına göre ülke hanedanın ortak malıydı; bu durum her hanedan üyesine taht hakkı vererek mücadelelere yol açtı.'),
  ('Büyük Selçuklu Devleti\'nin son büyük sultanı kabul edilen ve uzun süre Horasan meliki olarak görev yapan hükümdar kimdir?', 'Sencer', ['Berkyaruk', 'Muhammed Tapar', 'II. Tuğrul'], 'Sultan Sencer 1118-1157 arasında Büyük Selçuklu sultanı oldu; ölümüyle devlet fiilen sona erdi.'),
  ('Sultan Sencer\'in 1141\'de Semerkant yakınlarında ağır bir yenilgi aldığı savaş hangisidir?', 'Katvan Savaşı', ['Dandanakan Savaşı', 'Kösedağ Savaşı', 'Yassıçemen Savaşı'], 'Katvan Savaşı\'nda Karahıtaylar Sencer\'i yendi; Maveraünnehir Selçuklu egemenliğinden çıktı.'),
  ('Sultan Sencer\'in esaretten kurtulduktan kısa süre sonra 1157\'de ölmesi Büyük Selçuklu Devleti için ne anlam taşır?', 'Devletin fiilen dağılması', ['Devletin Anadolu\'ya taşınması', 'Devletin yeniden altın çağına girmesi', 'Devletin Gaznelilerle birleşmesi'], 'Sencer\'in ölümünden sonra merkezî otorite kalmadı; topraklar atabeyliklere ve Harzemşahlara bölündü.'),
  ('Büyük Selçuklu Devleti\'nde sultanın oğullarına ya da hanedan üyelerine yönetmeleri için verilen eyaletlerin başındaki kişilere ne ad verilirdi?', 'Melik', ['Subaşı', 'Kadı', 'Müstevfi'], 'Hanedan üyeleri melik unvanıyla eyaletlere gönderilir, yanlarında yetişmeleri için atabeyler bulunurdu.'),
  ('Selçuklularda meliklerin yanında bulunan, onların eğitiminden ve eyalet yönetiminden sorumlu deneyimli devlet adamına ne denirdi?', 'Atabey', ['Emir-i dad', 'Pervane', 'Tuğrai'], 'Atabeyler meliklerin hem eğitmeni hem de yöneticisiydi; merkezî otorite zayıflayınca birçok atabey kendi devletini kurdu.'),
  ('Selçuklu divan teşkilatında ordunun ihtiyaçlarıyla, askerlerin kayıtlarıyla ve maaşlarıyla ilgilenen divan hangisidir?', 'Divan-ı Arz', ['Divan-ı İşraf', 'Divan-ı Tuğra', 'Divan-ı İstifa'], 'Divan-ı Arz\'ın başındaki görevliye \'Emir-i Arız\' denirdi ve askerî işlerden sorumluydu.'),
  ('Bir Selçuklu memuru, devletin gelir ve giderlerini kaydediyor ve bütçeyi düzenliyor. Bu memur hangi divanda görev yapmaktadır?', 'Divan-ı İstifa', ['Divan-ı Arz', 'Divan-ı İşraf', 'Divan-ı Tuğra'], 'Divan-ı İstifa mali işlerden sorumluydu; başındaki görevliye müstevfi denirdi.'),
  ('Selçuklularda devletin vergi gelirini bir bölgede askerî hizmet karşılığında bir komutana bırakmasına dayanan sistem hangisidir?', 'İkta', ['Vakıf', 'Mülk', 'İltizam'], 'İkta sisteminde toprağın mülkiyeti devlette kalır, vergi geliri hizmet karşılığında ikta sahibine bırakılırdı.'),
  ('İkta sistemini ilk kez büyük ölçekte ve düzenli biçimde uygulayan Selçuklu devlet adamı kimdir?', 'Nizamülmülk', ['Amidülmülk Kündüri', 'Alparslan', 'Tuğrul Bey'], 'İkta Büveyhiler döneminde de bilinmekle birlikte Nizamülmülk bu sistemi geliştirerek Selçuklu ülkesinin geneline yaydı.'),
  ('Bir ikta sahibi, köylüden aldığı vergiyle belirli sayıda atlı asker besliyor, savaş zamanında bu askerlerle sultanın ordusuna katılıyor. Bu uygulama devlete hangi açıdan fayda sağlar?', 'Merkezî hazineye yük olmadan büyük bir ordu bulundurmak', ['Köylülerin vergiden tamamen muaf tutulup yalnız askerlik yapması', 'İkta sahibinin bağımsız bir devlet kurabilmesi', 'Ticaretin devlet tekeline girmesi'], 'İkta sistemi sayesinde asker maaşları yerinde toplanan vergilerle karşılanır, para ekonomisinin yetersizliği aşılırdı.'),
  ('Nizamülmülk\'ün kurduğu Nizamiye medreselerinin ilki ve en ünlüsü hangi şehirde açılmıştır?', 'Bağdat', ['Nişabur', 'İsfahan', 'Merv'], 'İlk ve en ünlü Nizamiye Medresesi 1067\'de Bağdat\'ta açıldı; Nişabur, İsfahan ve Merv gibi şehirlerde de şubeleri kuruldu.'),
  ('Nizamiye medreselerinde öğrencilerin ücretsiz okuması, yemek ve barınma ihtiyaçlarının karşılanması hangi kaynakla sağlanırdı?', 'Vakıf gelirleriyle', ['Öğrencilerin ailelerinden alınan ücretlerle', 'Halifenin kişisel bağışlarıyla', 'Ordudan ayrılan ganimet paylarıyla'], 'Medreselere bağlanan vakıf gelirleri sayesinde eğitim ücretsizdi; müderrislere maaş, öğrencilere burs verilirdi.'),
  ('Musul ve Halep merkezli kurulan, Haçlılara karşı mücadelesiyle tanınan ve 1144\'te Urfa\'yı Haçlılardan geri alan atabeylik hangisidir?', 'Zengiler', ['Böriler', 'Salgurlular', 'İldenizliler'], 'İmadeddin Zengi 1144\'te Urfa Kontluğu\'nu yıkarak Haçlılardan ilk büyük şehri geri aldı; bu olay II. Haçlı Seferi\'ne yol açtı.'),
  ('1218\'de Cengiz Han\'ın gönderdiği ticaret kervanının bir Harzemşah valisi tarafından öldürülmesi olayı hangi şehirde yaşanmıştır?', 'Otrar', ['Buhara', 'Semerkant', 'Gürgenç'], 'Otrar valisi İnalcık (Gayır Han) kervanı casuslukla suçlayıp öldürttü; bu olay Moğol istilasının doğrudan nedeni oldu.'),
  ('Otrar olayının ardından başlayan Moğol saldırılarıyla Harzemşah ülkesinde Buhara, Semerkant ve Merv gibi şehirlerin yıkılması İslam dünyası için hangi sonucu doğurmuştur?', 'Orta Asya\'daki kültür ve bilim merkezlerinin büyük zarar görmesi', ['İslam dünyasının siyasi birliğinin Moğollara karşı hızla güçlenmesi', 'Moğolların hemen Müslüman olması', 'Haçlı Seferlerinin sona ermesi'], 'Moğol istilası kütüphaneleri, medreseleri ve şehirleri yok ederek Türk-İslam medeniyetine ağır bir darbe vurdu.'),
  ('Moğol istilası sonucunda Türkistan\'dan kaçan Türkmen ve bilginlerin büyük bölümünün hangi bölgeye göç etmesi, bu bölgenin Türkleşmesini hızlandırmıştır?', 'Anadolu', ['Hindistan', 'Kırım', 'Mısır'], 'Moğol baskısından kaçan Türkmenler, dervişler ve bilginler Anadolu\'ya yerleşti; Mevlana\'nın ailesi de bu göçe katıldı.'),
  ('Babası Alaeddin Muhammed\'in ölümünden sonra Moğollara karşı yıllarca mücadele eden Harzemşah hükümdarı kimdir?', 'Celaleddin Harzemşah', ['Alaeddin Tekiş Harzemşah', 'Atsız', 'İl Arslan'], 'Celaleddin Mengüberti, Sind Nehri kıyısında Cengiz Han\'a karşı savaştı ve ardından İran ile Azerbaycan\'da yeniden devlet kurmaya çalıştı.'),
  ('Malazgirt Savaşı\'ndan sonra Sivas, Tokat, Amasya ve Kayseri çevresinde kurulan Türk beyliği hangisidir?', 'Danişmentliler', ['Saltuklular Beyliği', 'Mengücekliler', 'Artuklular'], 'Danişment Gazi tarafından kurulan beylik Orta ve Kuzey Anadolu\'da etkili oldu; Sivas beyliğin merkezlerindendi.'),
  ('Danişmentliler Beyliği\'ne 1178\'de son veren Türkiye Selçuklu sultanı kimdir?', 'II. Kılıçarslan', ['I. Kılıçarslan', 'I. Mesud', 'I. Alaeddin Keykubat'], 'II. Kılıçarslan Danişmentli topraklarını ele geçirerek Anadolu\'da Türk siyasi birliğinin sağlanmasında önemli bir adım attı.'),
  ('Erzurum merkezli kurulan ve Anadolu\'daki ilk Türk beyliklerinden sayılan beylik hangisidir?', 'Saltuklular', ['Mengücekliler', 'Danişmentliler', 'Çaka Beyliği'], 'Ebu\'l-Kasım Saltuk Bey tarafından kurulan Saltuklular, Erzurum ve çevresinde hüküm sürdü.'),
  ('Erzincan, Kemah ve Divriği çevresinde hüküm süren beylik hangisidir?', 'Mengücekliler', ['Saltuklular', 'Artuklular', 'Danişmentliler'], 'Mengücek Gazi tarafından kurulan beylik, Erzincan ve Divriği kolları olmak üzere iki koldan yönetildi.'),
  ('Hasankeyf, Mardin ve Harput kollarına ayrılarak hüküm süren beylik hangisidir?', 'Artuklular', ['Mengücekliler', 'Danişmentliler', 'Saltuklular'], 'Artuk Bey\'in oğulları tarafından kurulan beylik Hasankeyf, Mardin-Mayyafarikin ve Harput olmak üzere üç kola ayrıldı.'),
  ('Artuklu sarayında yaşamış ve otomatik makineler üzerine yazdığı eseriyle sibernetiğin öncüleri arasında sayılan bilgin kimdir?', 'El-Cezeri', ['Biruni', 'Harezmi', 'Ali Kuşçu'], 'El-Cezeri 1206 civarında tamamladığı \'Kitab fi Ma\'rifeti\'l-Hiyeli\'l-Hendesiyye\' adlı eserinde su saatleri ve otomatlar tasarladı.'),
  ('İzmir\'de kurulan, donanma oluşturarak Ege adalarını ele geçiren ve Bizans\'ı denizden kuşatmaya çalışan Türk beyi kimdir?', 'Çaka Bey', ['Danişment Gazi', 'Saltuk Bey', 'Artuk Bey'], 'Çaka Bey Türk tarihinde ilk donanmayı kuran beylerdendir; Midilli, Sakız ve Sisam gibi adaları aldı.'),
  ('Birinci Beylikler Dönemi\'nde Anadolu\'da kurulan beyliklerin ortak özelliği aşağıdakilerden hangisidir?', 'Malazgirt Savaşı\'ndan sonra kurulmaları', ['Moğollara bağlı olarak kurulmaları', 'Osmanlı Devleti tarafından yıkılmaları', 'Tümünün Akdeniz kıyısında kurulmuş olması'], 'Saltuklu, Mengücekli, Danişmentli, Artuklu ve Çaka beylikleri Malazgirt\'ten sonra Anadolu\'nun fethi sırasında kuruldu.'),
  ('Birinci Beylikler Dönemi\'nde beyliklerin büyük çoğunluğunun ortadan kaldırılıp Anadolu\'da siyasi birliğin sağlanmasında hangi devlet başrolü oynamıştır?', 'Türkiye Selçuklu Devleti', ['Büyük Selçuklu Devleti\'nin melikleri', 'İlhanlı Devleti', 'Memlük Devleti'], 'Türkiye Selçuklu sultanları, özellikle II. Kılıçarslan ve sonrası, beylikleri tek tek ortadan kaldırarak Anadolu\'yu birleştirdi.'),
  ('I. Haçlı Seferi sırasında Türkiye Selçuklularının başkenti İznik\'in 1097\'de kaybedilmesi üzerine devletin yeni merkezi neresi olmuştur?', 'Konya', ['Kayseri', 'Sivas', 'Malatya'], 'İznik\'in Haçlılar ve Bizans tarafından alınmasından sonra Türkiye Selçukluları başkenti Konya\'ya taşıdı.'),
  ('I. Kılıçarslan\'ın I. Haçlı ordusuna karşı 1097\'de Eskişehir yakınlarında yaptığı ve kaybettiği savaş hangisidir?', 'Dorylaion (Eskişehir) Savaşı', ['Miryokefalon (Denizli) Savaşı', 'Malazgirt Savaşı', 'Hıttin Savaşı'], 'Dorylaion yenilgisinden sonra Kılıçarslan, Haçlıların önünde yerleşim alanlarını boşaltarak yıpratma taktiği uyguladı.'),
  ('Haçlı Seferleri\'nin dinî nedenlerinden biri olarak aşağıdakilerden hangisi gösterilebilir?', 'Kudüs\'ü Hristiyanlar adına ele geçirme isteği', ['Venedik\'in Doğu Akdeniz ticaret yollarını denetleme isteği', 'Feodal beylerin yeni topraklar kazanma arzusu', 'Avrupa\'daki nüfus artışı ve kıtlık'], 'Kudüs\'ün Hristiyanlarca kutsal sayılması ve Papa\'nın çağrısı seferlerin dinî gerekçesini oluşturdu; diğerleri ekonomik ve sosyal nedenlerdir.'),
  ('II. Haçlı Seferi\'nin düzenlenmesine doğrudan yol açan olay hangisidir?', 'Zengilerin Urfa\'yı geri alması', ['Selahaddin\'in Kudüs\'ü alması', 'Latinlerin İstanbul\'u işgal etmesi', 'Memlüklerin Akka\'yı fethetmesi'], 'İmadeddin Zengi\'nin 1144\'te Urfa\'yı alması, Avrupa\'da yeni bir sefer çağrısına neden oldu.'),
  ('III. Haçlı Seferi\'ne yol açan olay, 1187\'de Hıttin Savaşı\'ndan sonra Kudüs\'ün kimin tarafından alınmasıdır?', 'Selahaddin Eyyubi', ['Nureddin Mahmud Zengi', 'Baybars', 'İmadeddin Zengi'], 'Selahaddin Eyyubi 1187\'de Kudüs\'ü geri aldı; bunun üzerine Avrupa\'nın üç büyük hükümdarı III. Haçlı Seferi\'ni başlattı.'),
  ('II. Kılıçarslan\'ın 1176\'da Bizans İmparatoru Manuel Komnenos\'u yendiği savaş hangisidir?', 'Miryokefalon Savaşı', ['Malazgirt (Manzikert) Savaşı', 'Dorylaion Savaşı', 'Kösedağ Savaşı'], 'Denizli-Eğirdir arasında Myriokephalon geçidinde yapılan savaşta Bizans ordusu pusuya düşürülerek ağır bir yenilgiye uğradı.'),
  ('Miryokefalon Savaşı\'nın en önemli sonucu olarak aşağıdakilerden hangisi kabul edilir?', 'Bizans\'ın Anadolu\'yu Türklerden geri alma umudunun sona ermesi', ['Türklerin İstanbul\'u fethetmesi', 'Haçlı Seferleri\'nin tamamen durması', 'Türkiye Selçuklularının yeniden Büyük Selçuklulara bağlanması'], 'Malazgirt Anadolu\'nun kapısını açmış, Miryokefalon ise Anadolu\'nun kesin olarak Türk yurdu olduğunu kanıtlamıştır.'),
  ('III. Haçlı Seferi sırasında Alman imparatoru Frederik Barbarossa\'nın ordusunun kısa süreliğine ele geçirdiği Türkiye Selçuklu başkenti hangisidir?', 'Konya', ['Kayseri', 'Sivas', 'Akşehir'], 'Barbarossa 1190\'da Konya\'yı geçici olarak işgal etti; ardından güneye ilerleyerek Silifke\'ye ulaştı.'),
  ('Türkiye Selçuklu sultanı I. Gıyaseddin Keyhüsrev\'in 1207\'de fethettiği ve Selçuklulara Akdeniz\'de ilk büyük liman kazandıran şehir hangisidir?', 'Antalya', ['Alanya', 'Sinop', 'Mersin'], 'Antalya\'nın alınmasıyla Selçuklular Akdeniz ticaretine doğrudan açıldı; Mısır ve İtalyan şehirleriyle ticaret gelişti.'),
  ('I. İzzeddin Keykavus\'un 1214\'te Trabzon Rum İmparatorluğu\'ndan aldığı Karadeniz limanı hangisidir?', 'Sinop', ['Samsun', 'Trabzon', 'Giresun'], 'Sinop\'un fethiyle Selçuklular Karadeniz ticaretine katıldı ve Kırım ile ticaret yolu açıldı.'),
  ('Türkiye Selçuklularının en parlak dönemini yaşadığı sultan olarak kabul edilen hükümdar kimdir?', 'I. Alaeddin Keykubat', ['II. Gıyaseddin Keyhüsrev', 'I. Kılıçarslan', 'II. Kılıçarslan'], 'I. Alaeddin Keykubat (1220-1237) döneminde devlet siyasi, ekonomik ve kültürel açıdan zirveye ulaştı.'),
  ('I. Alaeddin Keykubat\'ın 1221\'de ele geçirip kış başkenti yaptığı ve adını \'Alaiye\' olarak değiştirdiği şehir hangisidir?', 'Alanya', ['Antalya', 'Manavgat', 'Silifke'], 'Kalonoros Kalesi\'ni alan Alaeddin Keykubat şehre Alaiye adını verdi; burada tersane ve Kızıl Kule\'yi yaptırdı.'),
  ('I. Alaeddin Keykubat\'ın Beyşehir Gölü kıyısında yaptırdığı saray hangisidir?', 'Kubadabad Sarayı', ['Topkapı Sarayı', 'Keykubadiye Sarayı', 'Alara Sarayı'], 'Kubadabad Sarayı\'ndan çıkarılan çiniler, Selçuklu saray sanatının ve figürlü çini geleneğinin önemli örnekleridir.'),
  ('I. Alaeddin Keykubat\'ın 1237\'de ölümünden sonra tahta geçen ve döneminde Kösedağ yenilgisinin yaşandığı sultan kimdir?', 'II. Gıyaseddin Keyhüsrev', ['I. İzzeddin Keykavus', 'II. İzzeddin Keykavus', 'III. Gıyaseddin Keyhüsrev'], 'II. Gıyaseddin Keyhüsrev döneminde Babai isyanı ve 1243 Kösedağ yenilgisi yaşandı; devlet hızla çöküşe girdi.'),
  ('1240 yılında Türkiye Selçuklularına karşı Türkmenler arasında başlayan ve Baba İlyas ile Baba İshak\'ın öncülük ettiği ayaklanma hangisidir?', 'Babai İsyanı', ['Celali İsyanı', 'Cimri Olayı', 'Batıni İsyanı'], 'Babai İsyanı Türkmenlerin ekonomik sıkıntıları ve yönetimden hoşnutsuzluğu üzerine çıktı; güçlükle bastırılabildi.'),
  ('Kösedağ Savaşı\'ndan sonra Türkiye Selçuklu Devleti\'nin durumu aşağıdakilerden hangisiyle açıklanır?', 'Moğollara vergi veren bağımlı bir devlet hâline gelmiştir', ['Moğolları yenerek sınırlarını Azerbaycan\'a kadar genişletmiştir', 'Bizans\'a bağlanmıştır', 'Memlüklerle birleşmiştir'], 'Kösedağ\'dan sonra Selçuklular Moğol egemenliğini tanıdı; vergi ödedi ve sultanlar Moğolların onayıyla tahta çıkmaya başladı.'),
  ('Kösedağ Savaşı\'ndan sonra Anadolu\'da Moğol baskısından uzak uç bölgelerde yeni Türkmen beyliklerinin ortaya çıkması hangi gelişmeyle doğrudan ilgilidir?', 'Selçuklu merkezî otoritesinin zayıflaması', ['Haçlı Seferlerinin yeniden başlayıp Anadolu\'ya yönelmesi', 'Bizans\'ın Anadolu\'yu geri alması', 'Abbasi halifeliğinin güçlenmesi'], 'Merkezî otoritenin çökmesi uç beylerini bağımsızlaşmaya yöneltti; Anadolu\'da Beylikler Dönemi başladı.'),
  ('Karamanoğlu Mehmet Bey\'in 1277\'de Konya\'yı ele geçirip Türkçeyi resmî dil ilan ettiği ferman sırasında tahta çıkarılan sahte Selçuklu şehzadesine ne ad verilmiştir?', 'Cimri', ['Kılıçarslan', 'Keykubat', 'Mesud'], 'Kendini II. İzzeddin Keykavus\'un oğlu olarak tanıtan Siyavuş, halk arasında \'Cimri\' diye anıldı.'),
  ('Karamanoğlu Mehmet Bey\'in 1277\'de çıkardığı fermanın Türk dili tarihindeki önemi nedir?', 'Divan, dergâh ve çarşıda yalnız Türkçe konuşulmasını emretmesi', ['Arap alfabesini yasaklaması', 'Farsçayı bütün divan yazışmalarında resmî dil yapması', 'Uygur alfabesini yeniden kullanıma sokması'], 'Mehmet Bey \'Bugünden sonra divanda, dergâhta, bargâhta, mecliste ve meydanda Türkçeden başka dil kullanılmayacaktır\' diyerek Türkçeyi resmî dil ilan etti.'),
  ('Türkiye Selçuklularında yol boyunca yaklaşık bir günlük yürüyüş mesafesiyle kurulan ve tüccarlara konaklama imkânı sunan yapılara ne ad verilir?', 'Kervansaray', ['Bedesten', 'Arasta', 'İmaret'], 'Kervansaraylar ticaret yolları üzerinde, kervanların günlük yolculuk mesafesine göre yaklaşık 30-40 km arayla inşa edildi.'),
  ('Selçuklu kervansaraylarında konaklayan tüccarlara üç gün boyunca yemek, barınma ve hayvanlarının bakımı gibi hizmetlerin ücretsiz verilmesi hangi amaca yöneliktir?', 'Ticareti teşvik ederek ülkeyi ticaret merkezi yapmak', ['Tüccarlardan daha yüksek gümrük vergisi alarak hazineyi doldurmak', 'Yabancı tüccarların ülkeye girişini zorlaştırmak', 'Kervansarayları askerî kışlaya dönüştürmek'], 'Ücretsiz hizmetler tüccarları Selçuklu topraklarından geçmeye özendirdi; transit ticaret devlete büyük gelir sağladı.'),
  ('Türkiye Selçuklularında yol üzerinde soyguna uğrayan tüccarın zararının devlet tarafından karşılanması uygulaması, günümüzdeki hangi kavrama benzer?', 'Sigorta', ['Kredi', 'Gümrük birliği', 'Serbest bölge'], 'Devlet sigortası uygulamasıyla tüccarın kaybı hazineden ödenirdi; bu da yolların güvenli kabul edilmesini sağladı.'),
  ('Konya-Aksaray arasındaki Selçuklu ticaret yolu üzerinde bulunan ve en büyük Selçuklu kervansaraylarından biri olan yapı hangisidir?', 'Sultanhanı', ['Taşhan', 'Kapan Han', 'Kurşunlu Han'], 'I. Alaeddin Keykubat tarafından 1229\'da yaptırılan Aksaray Sultanhanı, Anadolu\'nun en büyük kervansaraylarındandır.'),
  ('Türkiye Selçuklularının ticaret yollarını güvenli kılmak için aldığı önlemlerden biri aşağıdakilerden hangisi değildir?', 'Yabancı tüccarlara ülkeye girişi yasaklamak', ['Yollara karakollar kurmak', 'Kervansaraylar inşa etmek', 'Tüccarların yolda uğradığı kayıpları hazineden karşılamak'], 'Selçuklular yabancı tüccarları teşvik etti; Venedik ve Cenova gibi devletlerle ticaret antlaşmaları yaptı.'),
  ('Konya\'da bulunan ve kubbesindeki çinileriyle ünlü, günümüzde çini eserleri müzesi olarak kullanılan Selçuklu medresesi hangisidir?', 'Karatay Medresesi', ['İnce Minareli Medrese', 'Çifte Minareli Medrese', 'Buruciye Medresesi'], 'Celaleddin Karatay\'ın 1251\'de yaptırdığı medrese, firuze çinileriyle ünlüdür ve Çini Eserler Müzesi olarak hizmet verir.'),
  ('Türkiye Selçuklu döneminde ölüler için yapılan, genellikle silindirik ya da çokgen gövdeli, külahlı mezar yapılarına ne denir?', 'Kümbet', ['Tekke', 'İmaret', 'Şifahane'], 'Kümbetler Ahlat, Kayseri ve Erzurum gibi şehirlerde sıkça görülür; bozkır çadırının taşa dönüşmüş hâli olarak yorumlanır.'),
  ('Selçuklularda hastane işlevi gören ve tıp eğitimi de verilen kurumlara ne ad verilirdi?', 'Darüşşifa', ['Darülhadis', 'Darülkurra', 'Darülaceze'], 'Darüşşifa, maristan ya da bimarhane adıyla da anılırdı; Kayseri Gevher Nesibe Darüşşifası bunun bilinen örneklerindendir.'),
  ('Sivas\'ta bulunan ve taç kapısındaki mavi çinilerinden ötürü adını alan, Sahip Ata Fahreddin Ali\'nin yaptırdığı medrese hangisidir?', 'Gök Medrese', ['Buruciye Medresesi', 'Şifaiye Medresesi', 'Çifte Minareli Medrese'], 'Sivas Gök Medrese 1271\'de Sahip Ata tarafından yaptırıldı; minarelerindeki firuze çiniler nedeniyle bu adı aldı.'),
  ('Konya\'da bulunan, kapısının kalın burmalı süslemeleri ve tek kalan ince minaresiyle tanınan Selçuklu medresesi hangisidir?', 'İnce Minareli Medrese', ['Karatay Medresesi', 'Sırçalı Medrese', 'Gök Medrese'], 'Sahip Ata Fahreddin Ali\'nin yaptırdığı İnce Minareli Medrese, taş işçiliği müzesi olarak kullanılmaktadır.'),
  ('Türkiye Selçuklu döneminde dokunan ve Marco Polo\'nun \'dünyanın en güzeli\' diye övdüğü ürün hangisidir?', 'Halı', ['Cam', 'Kâğıt', 'Porselen'], 'Konya ve Aksaray\'da dokunan Selçuklu halıları, Marco Polo\'nun seyahatnamesinde dünyanın en güzel ve ince halıları olarak anılır.'),
  ('Belh\'ten gelip Konya\'ya yerleşen ve Mesnevi adlı eseriyle tanınan mutasavvıf kimdir?', 'Mevlana Celaleddin Rumi', ['Hacı Bektaş Veli', 'Yunus Emre', 'Ahmet Yesevi'], 'Mevlana\'nın ailesi Moğol tehlikesi sırasında Anadolu\'ya göç etti; Mevlana Konya\'da yaşadı ve 1273\'te öldü.'),
  ('Mevlana\'nın düşünce dünyasında köklü bir değişime yol açan ve onunla 1244\'te Konya\'da karşılaşan derviş kimdir?', 'Şems-i Tebrizi', ['Sultanü\'l-Ulema Bahaeddin Veled', 'Sadreddin Konevi', 'Seyyid Burhaneddin'], 'Şems-i Tebrizi ile karşılaşma, Mevlana\'nın medrese âlimliğinden aşk ve vecd merkezli bir tasavvuf anlayışına yönelmesini sağladı.'),
  ('Horasan\'dan Anadolu\'ya gelerek Kırşehir yakınlarına yerleşen ve Makalat adlı eseriyle bilinen mutasavvıf kimdir?', 'Hacı Bektaş Veli', ['Mevlana', 'Yunus Emre', 'Ahi Evran'], 'Hacı Bektaş Veli 13. yüzyılda Sulucakarahöyük\'e yerleşti; öğretileri sonradan Bektaşilik adıyla teşkilatlandı.'),
  ('Sade Türkçeyle ve hece ölçüsüyle yazdığı ilahileriyle Anadolu\'da Türkçenin edebiyat dili olarak gelişmesine katkıda bulunan 13-14. yüzyıl şairi kimdir?', 'Yunus Emre', ['Mevlana', 'Ahmet Yesevi', 'Sultan Veled'], 'Yunus Emre\'nin Divan\'ı ve Risaletü\'n-Nushiyye\'si Anadolu Türkçesinin en önemli ilk örneklerindendir.'),
  ('Mevlana\'nın ölümünden sonra onun düşüncelerini tarikat hâlinde teşkilatlandıran oğlu kimdir?', 'Sultan Veled', ['Şems-i Tebrizi', 'Hüsameddin Çelebi', 'Bahaeddin Veled'], 'Mevlevilik, Mevlana\'nın oğlu Sultan Veled tarafından düzenli bir tarikat hâline getirildi.'),
  ('Türkiye Selçukluları döneminde esnaf ve sanatkârları bir araya getiren, mesleki eğitim yanında ahlaki eğitim de veren teşkilat hangisidir?', 'Ahilik', ['Loncacılık', 'Fütüvvet-i Bağdad', 'Vakıf'], 'Ahilik 13. yüzyılda Anadolu\'da Ahi Evran öncülüğünde yaygınlaştı; esnafın mesleki ve ahlaki gelişimini düzenledi.'),
  ('Ahi teşkilatının kurucusu kabul edilen ve Kırşehir\'de yaşamış debbağ (deri ustası) kimdir?', 'Ahi Evran', ['Ahi Mesud', 'Ahi Şerafeddin', 'Ahi Ahmed'], 'Ahi Evran (Şeyh Nasirüddin Mahmud) Kırşehir\'de debbağlık yaptı ve Ahi teşkilatını kurdu.'),
  ('Ahilikte mesleğe giren gencin çıraklık, kalfalık ve ustalık aşamalarından geçmesi aşağıdakilerden hangisini sağlamıştır?', 'Üretimde kalite ve mesleki ahlakın korunmasını', ['Fiyatların serbestçe belirlenmesini', 'Herkesin istediği mesleği izin almadan yapabilmesini', 'Esnafın vergiden muaf tutulmasını'], 'Aşamalı eğitim sistemi, ustanın denetiminde hem beceri hem ahlak kazandırarak kaliteli üretimi güvence altına aldı.'),
  ('Bir Ahi esnafının kusurlu mal satması üzerine ayakkabısının dama atılması (pabucunun dama atılması) uygulaması Ahiliğin hangi işlevini örnekler?', 'Esnafı denetleme ve yaptırım uygulama', ['Esnafa düşük faizle kredi verme', 'Yabancı tüccarla ticaret yapma', 'Askerlik görevini düzenleme'], 'Ahi teşkilatı kurallara uymayan esnafı teşhir ederek cezalandırırdı; \'pabucu dama atılmak\' deyimi buradan gelir.'),
  ('Selçuklu ve Beylikler döneminde Anadolu\'da kadınların teşkilatı olarak bilinen ve Ahiliğe benzer biçimde örgütlenen yapı hangisidir?', 'Bacıyan-ı Rum', ['Gaziyan-ı Rum', 'Abdalan-ı Rum', 'Fakiyan-ı Rum'], 'Âşıkpaşazade\'nin andığı dört zümreden biri olan Bacıyan-ı Rum, Anadolu kadınlarının örgütlenmesini ifade eder.'),
  ('Eyyubi Devleti\'nin son döneminde ordu komutanları tarafından Mısır\'da 1250\'de kurulan Türk devleti hangisidir?', 'Memlük Devleti', ['Tolunoğulları Devleti', 'İhşidiler', 'Fatımi Devleti'], 'Memlük, \'satın alınmış köle asker\' anlamına gelir; Kıpçak kökenli Memlükler Eyyubi hanedanına son verip kendi devletlerini kurdu.'),
  ('Ayn Calut Savaşı\'nın İslam dünyası açısından önemi nedir?', 'Moğolların Mısır\'a ve Kuzey Afrika\'ya ilerleyişini durdurmuştur', ['Haçlıların Kudüs\'ü Moğol desteğiyle yeniden almasını sağlamıştır', 'Abbasilerin Bağdat\'a dönmesini sağlamıştır', 'Bizans\'ın yıkılmasına yol açmıştır'], 'Ayn Calut zaferi Moğolların yenilmez olmadığını gösterdi ve Mısır\'ı Moğol istilasından korudu.'),
  ('Delhi\'de bulunan ve Kutbeddin Aybek döneminde yapımına başlanıp İltutmış döneminde tamamlanan ünlü minare hangisidir?', 'Kutub Minar', ['Çar Minar', 'Taç Mahal', 'Kalyan Minaresi'], 'Kutub Minar yaklaşık 73 metre yüksekliğiyle tuğladan yapılmış en yüksek minarelerdendir ve UNESCO Dünya Mirası\'ndadır.'),
  ('Delhi Türk Sultanlığı\'nın Moğol saldırılarına karşı direnmesi Hindistan açısından hangi sonucu doğurmuştur?', 'Hindistan\'ın Moğol yıkımından büyük ölçüde korunması', ['Hindistan\'ın Moğollara bağlanıp vergi ödemeye başlaması', 'Budizm\'in resmî din olması', 'Hindistan\'ın Bizans\'la birleşmesi'], 'Delhi sultanları, özellikle Alaeddin Halaci, Moğol akınlarını geri püskürterek Hindistan\'ı korudu.'),
  ('Cengiz Han\'ın torunu Batu Han tarafından İdil (Volga) Nehri havzasında kurulan ve zamanla Türkleşen devlet hangisidir?', 'Altın Orda Devleti', ['Çağatay Hanlığı Devleti', 'İlhanlı Devleti', 'Kırım Hanlığı'], 'Altın Orda nüfusunun büyük kısmı Kıpçak Türklerinden oluştuğu için kısa sürede Türkleşti; başkenti Saray şehriydi.'),
  ('Karamanoğulları Beyliği\'nin merkezi olan ve beyliğin uzun süre Konya ile birlikte elinde tuttuğu şehir hangisidir?', 'Larende (Karaman)', ['Kütahya', 'Kastamonu', 'Manisa (Saruhan merkezi)'], 'Karamanoğulları Larende\'yi merkez edindi; şehir sonradan beyliğin adıyla Karaman olarak anıldı.'),
  ('İzmir\'i merkez edinen ve Umur Bey döneminde Ege\'de güçlü bir donanmayla Latinlere karşı seferler yapan beylik hangisidir?', 'Aydınoğulları', ['Saruhanoğulları', 'Hamitoğulları', 'Eşrefoğulları'], 'Aydınoğlu Umur Bey, Ege adalarına ve Balkan kıyılarına deniz seferleri düzenledi; Gazavatname\'de kahramanlıkları anlatılır.'),
  ('Avrupa\'da \'Avicenna\' adıyla tanınan ve El-Kanun fi\'t-Tıb adlı eseri yüzyıllarca tıp okullarında okutulan bilgin kimdir?', 'İbn Sina', ['Farabi', 'Biruni', 'Ebu Bekir er-Razi'], 'İbn Sina Buhara yakınlarında doğdu; Kanun adlı eseri 17. yüzyıla kadar Avrupa üniversitelerinde ders kitabı olarak okutuldu.'),
  ('Cebir biliminin kurucusu sayılan ve adından \'algoritma\' kavramı türetilen bilgin kimdir?', 'Harezmi', ['Biruni', 'Farabi', 'Ali Kuşçu'], 'Harezmi\'nin El-Kitabü\'l-Muhtasar fi Hisabi\'l-Cebr ve\'l-Mukabele adlı eseri cebrin temelini attı; adının Latince söylenişi algoritma kelimesine dönüştü.'),
  ('Türk-İslam devletlerinde dinî kurallara dayanan hukuka şer\'i hukuk denirken, hükümdarın emir ve fermanlarına dayanan hukuka ne ad verilirdi?', 'Örfi hukuk', ['Fıkıh usulü hukuku', 'Kadılar meclisi hukuku', 'Sünnet ve icma hukuku'], 'Şer\'i hukukun boşluk bıraktığı alanlarda hükümdarın koyduğu kurallar örfi hukuku oluştururdu.'),
  ('Türk-İslam devletlerinde hükümdarın, ülkenin ve halkın adına cuma namazlarında okunan hutbede adının geçmesi neyi simgelerdi?', 'Hükümdarlık hakkının tanınmasını', ['Hükümdarın halife olduğunu', 'Hükümdarın vergi muafiyetini', 'Hükümdarın savaş ilan ettiğini'], 'Hutbe okutma, sikke kestirme gibi bağımsızlık sembollerindendi; bir bölgede kimin adına hutbe okunuyorsa o bölgenin hâkimi kabul edilirdi.'),
  ('Türk-İslam devletlerinde para basılması ve paranın üzerine hükümdar adının yazılması hangi kavramla ifade edilir?', 'Sikke', ['Hutbe', 'Nevbet', 'Çetr'], 'Sikke kestirmek, hükümdarın bağımsızlığını gösteren temel sembollerden biriydi.'),
  ('Türk-İslam devletlerinde nevbet vurdurmak ne anlama gelirdi?', 'Hükümdarlık alameti olarak belirli vakitlerde davul çaldırmak', ['Halifeye yıllık vergi göndermek', 'Sefer öncesi kurultay toplamak', 'Fethedilen şehre kadı atamak'], 'Nevbet, günün belirli saatlerinde hükümdar adına davul ve zurna çalınmasıydı ve egemenlik simgesi sayılırdı.'),
  ('Büyük Selçuklu Devleti 1040\'ta kurulmuş, Sultan Sencer\'in ölümüyle 1157\'de fiilen sona ermiştir. Buna göre devlet yaklaşık kaç yıl varlığını sürdürmüştür?', '117', ['107', '127', '97'], '1157 - 1040 = 117 yıl eder.'),
  ('Tolunoğulları, İhşidiler ve Memlükler aynı coğrafyada kurulmuştur. Bu devletlerin kurulduğu bölge hangisidir?', 'Mısır', ['Horasan', 'Anadolu', 'Maveraünnehir'], 'Üç Türk devleti de Mısır\'da kuruldu; Memlükler Suriye ve Hicaz\'a da hükmetti.'),
  ('Semerkant\'ta büyük bir rasathane kurduran ve \'Zic-i Gurgani\' adıyla da bilinen yıldız katalogunu hazırlatan Timurlu hükümdarı kimdir?', 'Uluğ Bey', ['Şahruh', 'Hüseyin Baykara', 'Timur'], 'Uluğ Bey, Timur\'un torunuydu; Semerkant\'taki rasathanede yaklaşık bin yıldızın konumunu içeren katalog hazırlandı.'),
  ('Timur\'un başkent yaptığı ve Gur-i Emir türbesinin bulunduğu şehir hangisidir?', 'Semerkant', ['Herat', 'Buhara', 'Tebriz'], 'Timur Semerkant\'ı imparatorluğunun merkezi yaptı; Gur-i Emir türbesinde kendisi ve Uluğ Bey gömülüdür.'),
  ('Agra\'da bulunan ve Babür hükümdarı Şah Cihan\'ın eşi Mümtaz Mahal için yaptırdığı anıt mezar hangisidir?', 'Taç Mahal', ['Kutub Minar', 'Kızıl Kale', 'Humayun Türbesi'], 'Taç Mahal 17. yüzyılda yapıldı; Türk-İslam, Fars ve Hint mimari unsurlarını bir araya getirir.'),
  ('Karakoyunlu Devleti\'ne 1467\'de son veren Türkmen hükümdarı kimdir?', 'Uzun Hasan', ['Kara Yusuf', 'Kadı Burhaneddin', 'Kara Yülük Osman'], 'Akkoyunlu hükümdarı Uzun Hasan 1467\'de Cihan Şah\'ı yenerek Karakoyunlu Devleti\'ni ortadan kaldırdı.'),
  ('Anadolu\'da Türk yönetimine geçen yerli Hristiyan halkın inanç özgürlüğünü korumaya devam etmesi, Türklerin yönetim anlayışının hangi özelliğine işaret eder?', 'Hoşgörülü bir yönetim anlayışına', ['Zorla din değiştirme politikasına', 'Yerli halkı sürgün etme politikasına', 'Kilise mallarına el koyma politikasına'], 'Selçuklular gayrimüslimlere zimmî statüsü tanıdı; can, mal ve inanç güvenliği sağlandı.'),
  ('Oğuz Türklerinin destanlarını ve hikâyelerini içeren, Anadolu ve Azerbaycan sahasında yazıya geçirilen eser hangisidir?', 'Dede Korkut Kitabı', ['Kutadgu Bilig', 'Divan-ı Hikmet', 'Mesnevi'], 'Dede Korkut Kitabı, Oğuzların göçebe yaşamını, değerlerini ve kahramanlıklarını on iki hikâyede anlatır.'),
  ('Selçuklu döneminde Anadolu\'ya gelen ve göçebe hayvancılıkla geçinen Türkmenlerin yaz aylarında serin yaylalara, kışın sıcak ovalara geçmesi hangi yaşam biçimini yansıtır?', 'Yaylak-kışlak düzenini', ['Kentli tüccar yaşamını', 'Kölelik temelli tarımı', 'Deniz ticaretini'], 'Yaylak-kışlak düzeni, bozkırdan getirilen konar-göçer yaşam biçiminin Anadolu\'daki devamıydı.'),
  ('Kutadgu Bilig\'de \'Dil insanın süsüdür; ama dil insanın başını da yer\' anlamına gelen öğütler, eserin hangi işlevini öne çıkarır?', 'Ahlaki öğüt verme işlevini', ['Tarih kaydı tutma işlevini', 'Sözlük hazırlama işlevini', 'Hukuk kuralı koyma işlevini'], 'Kutadgu Bilig siyasetname özelliği yanında ahlak ve görgü kurallarına dair öğütlerle de doludur.'),
  ('Büyük Selçuklu ordusunda \'Türkmen\' adıyla anılan unsurların devlete en önemli katkısı aşağıdakilerden hangisi olmuştur?', 'Sınır bölgelerinde fetih ve akın gücü oluşturmaları', ['Divan teşkilatını kurmaları', 'Medreselerde müderrislik yapmaları', 'Vergi kayıtlarını tutmaları'], 'Göçebe Türkmenler özellikle Bizans sınırında akınlar yaparak Anadolu\'nun fethinde öncü rol oynadı.'),
  ('Türkiye Selçuklularında \'Uç\' bölgelerine yerleştirilen Türkmen beylerinin temel görevi neydi?', 'Bizans sınırını korumak ve akınlar düzenlemek', ['Saray hazinesini yönetmek', 'Medreselerde ders vermek', 'Ticaret kervanlarına vergi koymak'], 'Uç beyleri sınır bölgelerinde savunma ve gaza görevini üstlenirdi; Kösedağ sonrası bu bölgelerde beylikler doğdu.'),
  ('Celaleddin Harzemşah\'ın Sind Nehri kıyısında Cengiz Han\'a yenildikten sonra atıyla nehri geçerek kurtulması, kaynaklarda hangi özelliğiyle anılmasına yol açmıştır?', 'Cesareti ve direnç gücüyle', ['Moğollara teslim olmasıyla', 'Halifeye sığınmasıyla', 'Barış yanlısı tutumuyla'], 'Cengiz Han\'ın bile takdir ettiği rivayet edilen bu kaçış, Celaleddin\'in yiğitliğinin simgesi olmuştur.'),
  ('Bir Selçuklu emiri malının gelirini bir çeşmenin bakımına ve bir medresenin giderlerine süresiz olarak ayırıyor. Bu uygulama hangi kurumla ilgilidir?', 'Vakıf', ['İkta', 'İltizam', 'Müsadere'], 'Vakıf, bir malın gelirinin kalıcı olarak hayır ve kamu hizmetine ayrılmasıdır.'),
  ('Türk-İslam devletlerinde vakıf sisteminin yaygınlaşması devletin hangi yükünü hafifletmiştir?', 'Eğitim, sağlık ve bayındırlık hizmetlerinin finansmanını', ['Ordunun tamamen dağıtılmasını', 'Halifeye ödenen vergiyi', 'Dış ticaret açığını'], 'Medrese, darüşşifa, kervansaray, çeşme ve köprüler büyük ölçüde vakıf gelirleriyle yapılıp yaşatıldı.'),
  ('Türk-İslam devletlerinde gayrimüslimlerden alınan ve askerlik yapmamalarının karşılığı olarak görülen baş vergisine ne ad verilir?', 'Cizye', ['Öşür', 'Haraç', 'Zekât'], 'Cizye yetişkin ve çalışabilecek durumdaki gayrimüslim erkeklerden alınırdı; kadınlar, çocuklar ve yaşlılar muaftı.'),
  ('Selçuklularda göçebe Türkmenlerin yaşadığı yerleşim birimine \'oba\' denirken, yerleşik köylülerin yaşadığı birime ne ad verilirdi?', 'Köy', ['Ordugâh', 'Ribat', 'Kışla'], 'Selçuklu Anadolu\'sunda konar-göçer Türkmenler obalar hâlinde yaşarken, yerleşik nüfus köy ve kasabalarda toplanırdı.'),
  ('Selçuklu medreselerinde dinî bilimlerin yanında matematik, astronomi ve tıp gibi derslerin de okutulması, medreselerin hangi niteliğini gösterir?', 'Hem dinî hem akli bilimleri öğreten kurumlar olduğunu', ['Yalnızca askerî eğitim verdiklerini', 'Sadece Kur\'an okumayı öğrettiklerini', 'Yalnızca saray çocuklarına açık olduklarını'], 'Medreselerde nakli ilimler yanında akli ilimler de okutulurdu; bazı medreseler tıp ya da astronomiye ayrılmıştı.'),
  ('Bir tarih öğretmeni \'Türkler İslamiyet\'i kabul ettikten sonra yeni bir medeniyet dairesine girdi.\' diyor. Bu yargıyı en iyi destekleyen gelişme hangisidir?', 'Türk mimarisinde cami ve medresenin yaygınlaşması', ['Türklerin at yetiştirmeyi bırakması', 'Türklerin Göktürk yazısını kullanmaya devam etmesi', 'Türklerin Çin\'e bağlanması'], 'Cami, medrese, kervansaray gibi yapı türleri ve Arap alfabesi, Türklerin İslam medeniyet dairesine girdiğini gösterir.'),
  ('Tolunoğullarının ve İhşidilerin Abbasi halifesine hutbe ve sikkede yer vermeye devam etmeleri neyi gösterir?', 'Halifeye sembolik bağlılığı sürdürdüklerini', ['Halifeye tamamen düşman olduklarını', 'Halife adına vergi topladıklarını', 'Fatımilere bağlı olduklarını'], 'Bu devletler fiilen bağımsız olsa da meşruiyet için halifenin adını hutbe ve sikkede korudu.'),
  ('Malazgirt Savaşı\'nın Cuma günü yapılması ve Alparslan\'ın savaştan önce beyaz giyinmesi, onun savaşa nasıl bir anlam yüklediğini gösterir?', 'Savaşı dinî bir görev olarak gördüğünü', ['Savaştan kaçmak istediğini', 'Bizans\'la anlaşma yapmak istediğini', 'Savaşı ticari bir mesele saydığını'], 'Alparslan Cuma namazı sonrasında kefen anlamında beyaz giyindi; bu, gaza anlayışını ve şehitliği göze aldığını gösterir.'),
  ('Batınilerin uyguladığı ve önceden seçilmiş devlet adamlarının fedailerce öldürülmesine dayanan yöntem, siyasi tarih açısından hangi kavramla nitelendirilir?', 'Siyasi suikast', ['Diplomatik müzakere', 'Açık meydan savaşı', 'Ekonomik ambargo'], 'Batıniler büyük ordularla değil fedailerin düzenlediği suikastlerle siyasi hedeflerine ulaşmaya çalıştı.'),
  ('Selçuklularda şehzadelerin küçük yaşta atabeylerin yanına verilerek eyaletlere gönderilmesinin temel amacı nedir?', 'Devlet yönetimi konusunda deneyim kazanmaları', ['Saraydan uzaklaştırılarak cezalandırılmaları', 'Askerlikten muaf tutulmaları', 'Ticaret öğrenmeleri'], 'Melik ve atabey sistemi, şehzadelerin yönetimi uygulamalı olarak öğrenmesini sağlamaya yönelikti.'),
  ('Türkiye Selçuklularında başkent Konya\'da bulunan ve birçok Selçuklu sultanının türbesini barındıran cami hangisidir?', 'Alaeddin Camii', ['Selimiye Camii', 'Sahib Ata Camii', 'Eşrefoğlu Camii'], 'Konya Alaeddin Tepesi\'ndeki cami I. Alaeddin Keykubat döneminde tamamlandı; avlusundaki kümbette sultanlar gömülüdür.'),
  ('Alanya\'da bulunan, sekizgen planlı ve tersaneyi korumak amacıyla yapılan Selçuklu yapısı hangisidir?', 'Kızıl Kule', ['Galata Kulesi', 'Kız Kulesi', 'Hıdırlık Kulesi'], 'Kızıl Kule 1226\'da I. Alaeddin Keykubat döneminde, Halep\'li mimar Ebu Ali tarafından yapıldı.'),
  ('I. Alaeddin Keykubat\'ın Alanya\'da tersane kurdurması devletin hangi alandaki gücünü artırma çabasını gösterir?', 'Denizcilik', ['Madencilik', 'Hayvancılık', 'Dokumacılık'], 'Alanya Tersanesi Selçukluların Akdeniz\'de donanma bulundurma ve ticaret yollarını koruma isteğinin ürünüdür.'),
  ('Konya\'da Mevlana\'nın türbesinin bulunduğu ve bugün müze olarak kullanılan yapının halk arasındaki adı nedir?', 'Yeşil Türbe', ['Döner Kümbet', 'Gök Kubbe', 'Kırkkızlar Kümbeti'], 'Mevlana\'nın türbesi, yeşil çinili kubbesinden dolayı Kubbe-i Hadra ya da Yeşil Türbe olarak anılır.'),
  ('Hacı Bektaş Veli\'nin düşüncesinde \'Eline, diline, beline sahip ol\' sözü hangi değerleri öne çıkarır?', 'Dürüstlük, söz ve ahlak temizliği', ['Savaşçılık ve ganimet', 'Ticaret ve zenginlik', 'Yönetimde sertlik'], 'Söz, insanın el (hırsızlık yapmama), dil (yalan ve dedikodu etmeme) ve bel (namus) bakımından temiz olmasını öğütler.'),
  ('Yunus Emre\'nin \'Gelin tanış olalım, işi kolay kılalım / Sevelim sevilelim, dünya kimseye kalmaz\' dizelerinde öne çıkan düşünce hangisidir?', 'İnsan sevgisi ve dünyanın geçiciliği', ['Cihan hâkimiyeti ülküsü', 'Ticaretin önemi', 'Göçebe yaşamın üstünlüğü'], 'Yunus Emre insanları sevgi ve kardeşliğe çağırırken dünyanın geçici olduğunu hatırlatır.'),
  ('Ayn Calut zaferinden kısa süre sonra Sultan Kutuz\'u öldürerek tahta çıkan Memlük sultanı kimdir?', 'Baybars', ['Kalavun', 'Aybek', 'el-Eşref Halil'], 'Rükneddin Baybars 1260\'ta Kutuz\'u öldürdü ve 1277\'ye kadar hüküm sürerek devletin asıl kurucusu sayıldı.'),
  ('Altın Orda hükümdarı Özbek Han döneminde İslamiyet\'in devlet dini hâline gelmesi, devletin hangi süreci tamamladığını gösterir?', 'Türkleşme ve İslamlaşma sürecini', ['Moğollaşma sürecini', 'Hristiyanlaşma sürecini', 'Bizans\'la birleşme sürecini'], 'Özbek Han (1313-1341) döneminde İslam resmî din oldu; halkın çoğunluğunu oluşturan Kıpçaklarla yönetici Moğollar kaynaştı.'),
  ('Memlük Devleti Mısır\'da hangi hanedanın yerine kurulmuştur?', 'Eyyubi hanedanının', ['Fatımi hanedanının', 'Tolunoğulları hanedanının', 'İhşidi hanedanının'], 'Memlükler, Eyyubi sultanı Turan Şah\'ı 1250\'de öldürerek yönetimi ele geçirdi.'),
  ('Ebu Müslim önderliğinde Emevilere karşı başlayan ve Abbasilerin iktidara gelmesini sağlayan hareket hangi bölgede başlamıştır?', 'Horasan', ['Hicaz', 'Mısır', 'Endülüs'], 'Abbasi ihtilali Horasan\'da başladı; Türklere yakın bu bölgenin halkı Emevi politikalarından hoşnutsuzdu.'),
  ('Türkler İslamiyet\'i kabul ettikten sonra en çok hangi mezhebi benimsemişlerdir?', 'Hanefi mezhebini', ['Maliki mezhebini', 'Hanbeli mezhebini', 'Zahiri mezhebini'], 'Hanefi mezhebinin akla ve örfe geniş yer vermesi, Türk geleneklerine uyumlu bulunmuş; Türklerin büyük çoğunluğu bu mezhebi benimsemiştir.'),
  ('Ahmet Yesevi\'nin öğrencilerinin \'Horasan erenleri\' adıyla Anadolu\'ya gelmesi Anadolu\'da hangi sonucu doğurmuştur?', 'Tasavvufi düşüncenin Türkmenler arasında yaygınlaşması', ['Anadolu\'nun Bizans\'a geri verilmesi', 'Anadolu\'da Budizm\'in yayılması', 'Anadolu\'da göçebeliğin tamamen sona ermesi'], 'Yesevi geleneğinden gelen dervişler Anadolu\'da zaviyeler kurarak İslam\'ı Türkmenlere sade bir dille anlattı.'),
  ('Edip Ahmet Yükneki\'nin Atabetü\'l-Hakayık\'ta \'Bilgi ile yol bulunur, bilgisizlik insanı karanlıkta bırakır\' anlamındaki öğütleri hangi değere vurgu yapar?', 'Bilginin önemine', ['Savaşçılığa', 'Zenginliğe', 'Göçebeliğe'], 'Atabetü\'l-Hakayık\'ın ilk bölümleri bilginin faydası ve bilgisizliğin zararı üzerinedir.'),
  ('İlhanlı Devleti\'nin kurucusu olan ve Anadolu\'yu da egemenliği altında tutan Moğol hükümdarı kimdir?', 'Hülagü Han', ['Batu Han', 'Ögeday Han', 'Kubilay Han'], 'Hülagü, 1256-1258 seferleriyle İran ve Irak\'ta İlhanlı Devleti\'ni kurdu; Anadolu Selçukluları da ona bağlandı.'),
  ('İlhanlıların Anadolu\'dan ağır vergiler toplaması, Anadolu halkı ve Selçuklu ekonomisi üzerinde hangi sonucu doğurmuştur?', 'Halkın yoksullaşması ve ekonominin bozulması', ['Ticaretin rekor düzeye çıkması', 'Halkın vergiden muaf tutulması', 'Kervansarayların sayısının ikiye katlanması'], 'Moğol vergileri halkı ezdi; kıtlık ve göçler yaşandı, devlet ekonomisi çöktü.'),
  ('Haçlı Seferleri sırasında kurulan ve hem askerî hem dinî nitelik taşıyan Tapınak Şövalyeleri ile Hastane Şövalyeleri gibi teşkilatlara genel olarak ne ad verilir?', 'Dinî-askerî tarikatlar', ['Lonca birlikleri', 'Feodal kontluklar', 'Şehir cumhuriyetleri'], 'Templar ve Hospitaller gibi örgütler hem rahip hem şövalye kimliği taşıyan dinî-askerî tarikatlardı.'),
  ('Bir öğrenci \'Selçuk Bey – Tuğrul Bey – Alparslan – Melikşah\' sıralamasını yapıyor. Bu sıralamanın ölçütü nedir?', 'Büyük Selçuklu tarihindeki önder ve hükümdarların zaman sırası', ['Hükümdarların yaşadıkları sürelerin uzunluğu', 'Kazandıkları savaşların sayısı', 'Doğdukları şehirlerin alfabetik sırası'], 'Selçuk Bey\'den sonra Tuğrul, Alparslan ve Melikşah sırasıyla Selçukluların başına geçmiştir.'),
  ('Aşağıdaki olaylar kronolojik olarak sıralandığında hangisi en sonda yer alır?', 'Ayn Calut Savaşı', ['Yassıçemen Savaşı', 'Kösedağ Savaşı', 'Katvan Savaşı'], 'Katvan 1141, Yassıçemen 1230, Kösedağ 1243, Ayn Calut 1260 yılındadır.'),
  ('Kayseri\'deki Gevher Nesibe Darüşşifası\'nın yanında tıp medresesinin bulunması günümüzdeki hangi kuruma benzetilebilir?', 'Tıp fakültesi hastanesine', ['Askerî kışlaya', 'Kervansaraya', 'Ticaret borsasına'], 'Hastane ile tıp okulunun birlikte bulunması, uygulamalı tıp eğitimi veren bugünkü üniversite hastanelerini andırır.'),
  ('Büyük Selçuklu sultanı Melikşah döneminde yapılan ve hac yolunun güvenliğini sağlamaya yönelik düzenlemeler hangi amaca hizmet eder?', 'Hacıların güvenli biçimde Mekke\'ye ulaşması', ['Haçlıların Kudüs\'e gelmesinin önlenmesi', 'Bizans\'a karşı yeni bir cephe açılması', 'Hindistan ticaretinin denetlenmesi'], 'Melikşah hac yolunda kuyular ve konaklama yerleri yaptırdı, bedevi saldırılarına karşı önlem aldı.'),
  ('Mengücekliler, Saltuklular ve Artuklular gibi beyliklerin Anadolu Selçuklularınca ortadan kaldırılması 13. yüzyılın başlarında hangi sonucu doğurmuştur?', 'Anadolu\'da Türk siyasi birliğinin büyük ölçüde sağlanması', ['Anadolu\'nun Bizans\'a geri dönmesi', 'Beyliklerin Moğollarla birleşmesi', 'Türkiye Selçuklularının Mısır\'a taşınması'], 'Beyliklerin Selçuklu topraklarına katılmasıyla Moğol istilasından önce Anadolu\'da güçlü bir merkezî yönetim oluştu.'),
  ('Bir tarih öğrencisi Anadolu Selçuklu dönemine ait bir kervansarayın kapı kitabesinde sultan adının yanında \'Sultanü\'l-Muazzam\' ifadesini okuyor. Bu ifade kitabenin hangi işlevini gösterir?', 'Yapıyı yaptıran hükümdarın unvanını kaydetme', ['Kervansarayın kira bedelini belirtme', 'Yolcuların kaç gün kalacağını gösterme', 'Yapının mimarının imzasını taşıma'], 'Kitabelerde hükümdarın ad ve unvanları yazılır; bu, yapının hangi sultan döneminde yapıldığını belgeler.'),
  ('Bir müze rehberi ziyaretçilere bir kervansarayın kalın duvarlı, burçlu ve tek kapılı olduğunu anlatıyor. Bu mimari özellik en çok hangi ihtiyaçla açıklanır?', 'Kervanları eşkıya saldırılarına karşı korumak', ['Kervansarayı süslü bir saray gibi göstermek', 'Kervansarayda tarım ürünü yetiştirmek', 'Yapıyı deprem sırasında kolay yıkılır hâle getirmek'], 'Kervansaraylar ıssız yollarda bulunduğundan kale gibi korunaklı yapılır, tek kapı güvenliği kolaylaştırırdı.'),
  ('Kösedağ Savaşı ile Ayn Calut Savaşı karşılaştırıldığında aşağıdaki yargılardan hangisi doğrudur?', 'İkisi de Moğollara karşı yapılmış, ilki yenilgi ikincisi zaferle sonuçlanmıştır', ['İkisi de Haçlılara karşı kazanılmış zaferlerdir', 'İkisi de Bizans\'a karşı yapılmıştır', 'İkisinde de Türk tarafı yenilmiştir'], '1243 Kösedağ\'da Selçuklular yenildi; 1260 Ayn Calut\'ta ise Memlükler Moğolları yendi.'),
  ('Bir öğretmen, Divan-ı Mezalim\'in işleyişini anlatırken \'Sultan, en yüksek görevliyi bile halkın şikâyeti üzerine yargılatabilirdi.\' diyor. Bu bilgi Selçuklu yönetiminin hangi ilkesine örnektir?', 'Adaletin herkese eşit uygulanması', ['Görevlilerin yargılanamaması', 'Sultanın hukuk dışı olması', 'Halkın şikâyet hakkının olmaması'], 'Mezalim mahkemeleri, güçlü görevlilerin de hesap verebildiği bir adalet anlayışını yansıtır.'),
  ('Ahi teşkilatının esnafa hem meslek hem ahlak eğitimi vermesi, günümüzde hangi uygulamaya en çok benzer?', 'Meslek odalarının ustalık belgesi ve meslek ahlakı kurallarına', ['Seçimle belediye başkanı belirlenmesine', 'Askerî akademilerdeki subay eğitimine', 'Bankaların kredi uygulamalarına'], 'Ahilik, mesleki yeterliliği ve ahlak kurallarını birlikte denetleyen bir esnaf örgütüydü; bu yönüyle meslek odalarını andırır.'),
  ('Bir öğrenci, Divriği Darüşşifası, Gevher Nesibe Darüşşifası ve Sivas Darüşşifası\'nı bir sunuda bir araya getiriyor. Sununun başlığı en uygun şekilde hangisi olabilir?', 'Anadolu Selçuklu döneminde sağlık kurumları', ['Osmanlı\'da kurulan ilk tersaneler', 'Karahanlı dönemi kervansarayları', 'Memlük Mısır\'ının askerî kışlaları'], 'Üç yapı da Anadolu Selçuklu ve beylikler döneminde kurulan hastane ve tıp eğitimi kurumlarıdır.'),
];
